import{_ as a,o as t,c as o,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"Ceph Performance Meeting 2020-10-01","description":"","frontmatter":{"title":"Ceph Performance Meeting 2020-10-01","date":"2020-10-01T00:00:00.000Z","updated":"2020-10-02T00:00:00.000Z","tags":["Ceph","分布式存储","性能优化","RocksDB","PG 日志"],"categories":["会议纪要","技术讨论"],"outline":"deep"},"headers":[],"relativePath":"posts/2020/Ceph_Performance_Meeting_2020-10-01.md","filePath":"posts/2020/Ceph_Performance_Meeting_2020-10-01.md","lastUpdated":1780459816000}'),s={name:"posts/2020/Ceph_Performance_Meeting_2020-10-01.md"};function n(l,e,i,c,h,P){return t(),o("div",null,[...e[0]||(e[0]=[r('<p>在 2020 年 10 月 1 日举行的 Ceph 性能会议上，研发团队讨论了多个与 Ceph 分布式存储系统性能相关的重要议题。</p><h2 id="关键细节" tabindex="-1">关键细节 <a class="header-anchor" href="#关键细节" aria-label="Permalink to &quot;关键细节&quot;">​</a></h2><ul><li><strong>新 PR 和更新 PR</strong>：本周，Igor 提交了一个关于 PG 移除优化的新 PR。Paul Kuzner 审查了一个关于并发检索设备数据的卷 PR，仍在进行中。此外，还有一个 PR 允许在 RocksDB 中动态调整级别，目前正在收集性能数据。</li><li><strong>PG 日志条目回收原型</strong>：Gabby 正在开发一个用于回收 PG 日志条目键的原型。初步测试显示，这可能显著增加数据库输入记录，并在压缩过程中增加工作量。</li><li><strong>替代方案讨论</strong>：讨论了三种替代方案：修改 RocksDB、创建独立的 PG 日志解决方案、以及控制 RocksDB 的写前日志（WAL）。还提到了 MyRocks 的实现，可能提供有用的参考。</li></ul><h2 id="讨论的主要议题" tabindex="-1">讨论的主要议题 <a class="header-anchor" href="#讨论的主要议题" aria-label="Permalink to &quot;讨论的主要议题&quot;">​</a></h2><ul><li><strong>PG 日志优化</strong>：讨论了优化 PG 日志以减少在 RocksDB 中的存储和处理开销的方法。提出了多种方法，包括修改 RocksDB 内部行为、创建独立解决方案、以及学习 MyRocks 的实现。</li><li><strong>性能和正确性权衡</strong>：讨论了在优化性能的同时保持系统正确性的方法，特别是在减少 PG 日志条目和重复条目时可能带来的风险。</li></ul><h2 id="决定的事项" tabindex="-1">决定的事项 <a class="header-anchor" href="#决定的事项" aria-label="Permalink to &quot;决定的事项&quot;">​</a></h2><ul><li><strong>进一步研究 MyRocks</strong>：决定进一步研究 MyRocks 的实现，了解其如何处理写前日志和事务，以寻找可能的优化点。</li><li><strong>继续探索 PG 日志优化方案</strong>：继续探索和评估不同的 PG 日志优化方案，包括修改 RocksDB、创建独立解决方案等。</li></ul><h2 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h2><ul><li><strong>阅读 MyRocks 相关文档</strong>：团队成员需要阅读 MyRocks 的设计文档和相关博客，了解其优化策略。</li><li><strong>继续测试和评估</strong>：继续对不同的 PG 日志优化方案进行测试和评估，收集性能数据，确保优化方案既提高性能又不影响系统的正确性。</li><li><strong>讨论和决策</strong>：在下次会议中，团队将根据收集的信息和测试结果，进一步讨论并决定最终的优化方案。</li></ul><h2 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to &quot;结论&quot;">​</a></h2><p>会议讨论了 PG 日志优化问题，提出了多种可能的解决方案，并决定进一步研究 MyRocks 的实现作为参考。团队将继续测试和评估不同的优化方案，确保在提高性能的同时保持系统的正确性。下次会议将继续讨论并决定最终的优化方案。</p>',11)])])}const g=a(s,[["render",n]]);export{d as __pageData,g as default};
